#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"

/* --------------------------------------------------------------------
 * Tunable kernel parameters
 * --------------------------------------------------------------------
 * ATAX_J_UNROLL controls the unrolling hint for the innermost loops in
 * the main kernel. It can be tuned per-architecture (e.g., 4, 8, 16).
 * GCC may ignore this hint if it is not profitable.
 */
#ifndef ATAX_J_UNROLL
# define ATAX_J_UNROLL 8
#endif


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn;
  fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
      x[i] = 1 + (i / fn);
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Use 'const' and 'restrict' on read-only arrays to help the compiler
 *    with alias analysis and enable more aggressive vectorization.
 *  - Keep a scalar accumulator 'temp' in a register to compute tmp[i]
 *    and then reuse it directly when updating y[], avoiding an extra
 *    load from tmp[] inside the second inner loop.
 *  - Hoist frequently used bounds into local constants to reduce
 *    repeated macro expansion and potential overhead.
 *  - Provide a tunable unroll factor for the inner loops via
 *    ATAX_J_UNROLL and use '#pragma GCC unroll' as a hint.
 *
 * The algorithm and numerical order of accumulation for each y[j] and
 * tmp[i] are preserved relative to the original code.
 */
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 const DATA_TYPE POLYBENCH_2D(A,M,N,m,n) restrict,
		 const DATA_TYPE POLYBENCH_1D(x,N,n) restrict,
		 DATA_TYPE POLYBENCH_1D(y,N,n) restrict,
		 DATA_TYPE POLYBENCH_1D(tmp,M,m) restrict)
{
  int i, j;

  /* Local copies of the polybench loop bounds. */
  const int _M = _PB_M;
  const int _N = _PB_N;

#pragma scop
  /* Initialize y to zero. */
  for (j = 0; j < _N; j++)
    y[j] = SCALAR_VAL(0.0);

  /* ATAX main computation:
   * tmp = A * x
   * y   = A^T * tmp
   *
   * We compute, for each row i:
   *   temp  = dot(A[i][:], x[:]);
   *   tmp[i] = temp;
   *   y[j]  += A[i][j] * temp;
   *
   * This keeps 'temp' in a register across both inner loops.
   */
  for (i = 0; i < _M; i++)
    {
      const DATA_TYPE *restrict Ai = A[i];
      DATA_TYPE temp = SCALAR_VAL(0.0);

      /* First inner loop: tmp[i] = sum_j A[i][j] * x[j] */
#pragma GCC ivdep
#pragma GCC unroll ATAX_J_UNROLL
      for (j = 0; j < _N; j++)
        temp = temp + Ai[j] * x[j];

      /* Store the final value once; it is not reloaded later. */
      tmp[i] = temp;

      /* Second inner loop: y[j] += A[i][j] * tmp[i]
       * Uses the same row Ai, reusing 'temp' from a register.
       */
#pragma GCC ivdep
#pragma GCC unroll ATAX_J_UNROLL
      for (j = 0; j < _N; j++)
        y[j] = y[j] + Ai[j] * temp;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
