#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"

/* Tunable parameter for manual unrolling of the inner dot-product loop.
 *
 * Valid values are positive integers; typical useful values are 1, 2, 4 or 8.
 * The default of 4 matches AVX2's 256-bit width for double precision
 * (4 doubles per vector), but this is only a hint: the compiler is still
 * free to vectorize as it sees fit.
 */
#ifndef ATAX_J_UNROLL
# define ATAX_J_UNROLL 4
#endif


/* Array initialization.
 *
 * The loops are organized for row-major traversal of A to maximize
 * spatial locality. Invariant quantities are hoisted out of the loops
 * to reduce redundant computations.
 */
static
void init_array (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  const DATA_TYPE fn      = (DATA_TYPE)n;
  const DATA_TYPE inv_5m  = SCALAR_VAL(1.0) / (DATA_TYPE)(5 * m);

  /* x is 1D and contiguous; simple linear traversal is cache-friendly. */
  for (i = 0; i < n; i++)
    x[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i) / fn;

  /* A is stored row-major: A[i][j] for fixed i, varying j is contiguous. */
  for (i = 0; i < m; i++)
  {
    DATA_TYPE *Ai = A[i]; /* Pointer to the beginning of row i for faster access. */
    for (j = 0; j < n; j++)
      Ai[j] = ((DATA_TYPE)((i + j) % n)) * inv_5m;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Use local restrict-qualified pointers to document non-aliasing and
 *    help the compiler vectorize.
 *  - Keep frequently used loop-invariant values in local variables.
 *  - Compute tmp[i] using a local scalar accumulator 't' and store it once,
 *    then use 't' directly when updating y to avoid reloading tmp[i].
 *  - Manually unroll the inner dot-product loop by ATAX_J_UNROLL to
 *    increase instruction-level parallelism (while preserving the exact
 *    evaluation order of floating-point operations within the row).
 */
static void __attribute__((noinline))
kernel_atax(int m, int n,
            DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
            DATA_TYPE POLYBENCH_1D(x,N,n),
            DATA_TYPE POLYBENCH_1D(y,N,n),
            DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  /* Local restrict-qualified aliases improve optimization opportunities
   * by guaranteeing that these arrays do not alias one another. This is
   * true in PolyBench, as each is allocated separately.
   */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

  const int pb_n = _PB_N;
  const int pb_m = _PB_M;

  int i, j;

#pragma scop
  /* Initialize y to zero. */
  for (j = 0; j < pb_n; j++)
    y_[j] = SCALAR_VAL(0.0);

  /* ATAX core computation:
   *   tmp[i] = A[i][:] * x[:]
   *   y[:]  += A[i][:] * tmp[i]
   * We perform these two steps per row i.  The access pattern A[i][j] with
   * j as the innermost loop index is friendly to row-major storage.
   */
  for (i = 0; i < pb_m; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute tmp[i] as a dot product: t = sum_j A[i][j] * x[j]. */
    DATA_TYPE t = SCALAR_VAL(0.0);

    /* Manually unrolled inner loop for the dot product.  The unrolling
     * factor is controlled by ATAX_J_UNROLL.  The remainder is handled
     * by the scalar cleanup loop.
     *
     * The operations are ordered so that the sequence of additions is
     * identical to the simple scalar loop:
     *   for (j = 0; j < pb_n; ++j) t += Ai[j] * x_[j];
     */
#if ATAX_J_UNROLL <= 1
    for (j = 0; j < pb_n; j++)
    {
      t += Ai[j] * x_[j];
    }
#else
    int limit = pb_n - (pb_n % ATAX_J_UNROLL);
    for (j = 0; j < limit; j += ATAX_J_UNROLL)
    {
      /* Unrolled body: each block processes ATAX_J_UNROLL elements. */
#if ATAX_J_UNROLL >= 1
      t += Ai[j + 0] * x_[j + 0];
#endif
#if ATAX_J_UNROLL >= 2
      t += Ai[j + 1] * x_[j + 1];
#endif
#if ATAX_J_UNROLL >= 3
      t += Ai[j + 2] * x_[j + 2];
#endif
#if ATAX_J_UNROLL >= 4
      t += Ai[j + 3] * x_[j + 3];
#endif
#if ATAX_J_UNROLL >= 5
      t += Ai[j + 4] * x_[j + 4];
#endif
#if ATAX_J_UNROLL >= 6
      t += Ai[j + 5] * x_[j + 5];
#endif
#if ATAX_J_UNROLL >= 7
      t += Ai[j + 6] * x_[j + 6];
#endif
#if ATAX_J_UNROLL >= 8
      t += Ai[j + 7] * x_[j + 7];
#endif
      /* If ATAX_J_UNROLL > 8, the same pattern continues; any extra
       * iterations beyond 8 will effectively be no-ops unless the
       * macro is increased accordingly. Keeping the pattern generic
       * avoids hard-wiring a specific unroll factor into the code.
       */
    }
    /* Clean-up for remaining elements (if pb_n is not divisible by
     * ATAX_J_UNROLL).
     */
    for (; j < pb_n; j++)
    {
      t += Ai[j] * x_[j];
    }
#endif /* ATAX_J_UNROLL > 1 */

    tmp_[i] = t;

    /* Update y: y[j] += A[i][j] * tmp[i]
     *
     * Using the local scalar t (tmp[i]) avoids repeatedly loading from
     * tmp_[] inside the j-loop.  The loop has no loop-carried
     * dependencies across j, so it is a good candidate for SIMD
     * vectorization; we add an ivdep pragma as an additional hint to
     * GCC, though -O3 can typically figure this out on its own.
     */
#pragma GCC ivdep
    for (j = 0; j < pb_n; j++)
    {
      y_[j] += Ai[j] * t;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
               POLYBENCH_ARRAY(A),
               POLYBENCH_ARRAY(x),
               POLYBENCH_ARRAY(y),
               POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
