     with alias analysis.
   - Flatten the 2D array A into a 1D pointer plus an explicit
     leading dimension (lda = n) to simplify address arithmetic.
   - Keep _PB_M and _PB_N as the actual loop bounds (as in PolyBench).
   - Manually unroll the y-update loop to increase ILP and help
     vectorization; the unroll factor is controlled by ATAX_Y_UNROLL.
*/
static void __attribute__((noinline))
kernel_atax(int m, int n,
	    DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
	    DATA_TYPE POLYBENCH_1D(x,N,n),
	    DATA_TYPE POLYBENCH_1D(y,N,n),
	    DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  /* Use local constants for PolyBench loop bounds. */
  const int pb_n = _PB_N;
  const int pb_m = _PB_M;

  /* Create local restrict pointers to help the optimizer.  The
     benchmark allocates these arrays separately, so aliasing between
     them does not occur in practice. */
  DATA_TYPE * restrict x_ptr   = &x[0];
  DATA_TYPE * restrict y_ptr   = &y[0];
  DATA_TYPE * restrict tmp_ptr = &tmp[0];

  /* Flatten A into a 1D pointer with an explicit leading dimension.
     The memory layout of A is row-major with 'n' columns. */
  DATA_TYPE * restrict A_ptr   = &A[0][0];
  const int lda = n;

  int i, j;

#pragma scop
  /* Initialize y to zero. This is kept as an explicit loop (instead of
     memset) to preserve strict C semantics and to make vectorization
     straightforward. */
  for (j = 0; j < pb_n; j++)
    y_ptr[j] = SCALAR_VAL(0.0);

  /* Main computation:
       tmp[i] = sum_j A[i][j] * x[j];
       y[j]  += A[i][j] * tmp[i];
     Implemented in a way that:
       - keeps the inner j-loops with unit-stride access to A and x,
       - keeps the accumulation into y contiguous,
       - lets the compiler vectorize both inner loops.
  */
  for (i = 0; i < pb_m; i++)
  {
    /* Pointer to the beginning of row i of A. */
    const DATA_TYPE * restrict Ai = A_ptr + (size_t)i * (size_t)lda;

    /* First, compute the row-wise dot product tmp[i] = A[i,:] * x. */
    DATA_TYPE acc = SCALAR_VAL(0.0);

    /* Inner product over j; contiguous access in both Ai and x_ptr. */
    for (j = 0; j < pb_n; j++)
      acc += Ai[j] * x_ptr[j];

    tmp_ptr[i] = acc;

    /* Second, update y with the scaled row: y += tmp[i] * A[i,:].
       We manually unroll this inner loop to increase instruction-level
       parallelism and to help the compiler generate wide SIMD code. */

#if ATAX_Y_UNROLL == 1

    for (j = 0; j < pb_n; j++)
      y_ptr[j] += Ai[j] * acc;

#elif ATAX_Y_UNROLL == 2

    for (j = 0; j + 1 < pb_n; j += 2)
    {
      y_ptr[j    ] += Ai[j    ] * acc;
      y_ptr[j + 1] += Ai[j + 1] * acc;
    }
    for (; j < pb_n; j++)
      y_ptr[j] += Ai[j] * acc;

#elif ATAX_Y_UNROLL == 4

    for (j = 0; j + 3 < pb_n; j += 4)
    {
      y_ptr[j    ] += Ai[j    ] * acc;
      y_ptr[j + 1] += Ai[j + 1] * acc;
      y_ptr[j + 2] += Ai[j + 2] * acc;
      y_ptr[j + 3] += Ai[j + 3] * acc;
    }
    for (; j < pb_n; j++)
      y_ptr[j] += Ai[j] * acc;

#endif
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
