#ifndef ATAX_DATA_ALIGNMENT
# define ATAX_DATA_ALIGNMENT POLYBENCH_ALIGNMENT
#endif

/* Helper for expressing alignment assumptions on 1D pointers.
 * For GCC/Clang this lets the compiler generate wider vector loads.
 * On other compilers it degrades to a no-op.
