#endif


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Initialize x: simple affine function of the index. */
  for (i = 0; i < n; i++)
    x[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i / fn);

  /* Precompute scale factor to avoid doing a division in the inner loop. */
  const DATA_TYPE inv_5m = SCALAR_VAL(1.0) /
                            (SCALAR_VAL(5.0) * (DATA_TYPE)m);

  /* Initialize A with a modular pattern, scaled by inv_5m. */
  for (i = 0; i < m; i++) {
    for (j = 0; j < n; j++) {
      int mod = (i + j) % n;
      A[i][j] = ((DATA_TYPE)mod) * inv_5m;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original algorithm (for reference):
 *
 *   for i in 0..M-1:
 *     tmp[i] = sum_j A[i][j] * x[j]
 *   for j in 0..N-1:
 *     y[j] = sum_i A[i][j] * tmp[i]
 *
 * The implementation below keeps the same mathematical computation but
 * improves data locality and reduces memory traffic by:
 *   - Using restrict-qualified, alignment-assumed local aliases to help
 *     the compiler generate better vectorized code.
 *   - Computing tmp[i] in a scalar accumulator and writing it once,
 *     instead of updating tmp[i] on every inner-loop iteration.
 *   - Reusing the accumulated tmp[i] value held in a register when
 *     updating y.
 */
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;
  (void)m; /* m is only used for array shape; silence unused warnings. */

  /* Concrete loop bounds resolved by PolyBench macros. Keeping them in
   * local consts makes it easier for the compiler to reason about them. */
  const int PB_N = _PB_N;
  const int PB_M = _PB_M;

  /* Local aliases with restrict and alignment assumptions.
   *  - Arrays are allocated by PolyBench with POLYBENCH_ALIGNMENT-byte
   *    alignment, which we mirror via ATAX_DATA_ALIGNMENT.
   *  - Marking them restrict reflects that these arrays do not alias,
   *    enabling more aggressive optimizations.
   */
#if defined(__GNUC__)
  const DATA_TYPE (*restrict A_)[n] =
    (const DATA_TYPE (*)[n])__builtin_assume_aligned(A, ATAX_DATA_ALIGNMENT);
#else
  const DATA_TYPE (*restrict A_)[n] = A;
#endif

  const DATA_TYPE *restrict x_  = ATAX_ASSUME_ALIGNED_1D(x);
  DATA_TYPE *restrict y_        = ATAX_ASSUME_ALIGNED_1D(y);
  DATA_TYPE *restrict tmp_      = ATAX_ASSUME_ALIGNED_1D(tmp);

#pragma scop
  /* y initialization: vectorizable, contiguous access. */
  for (i = 0; i < PB_N; i++)
    y_[i] = SCALAR_VAL(0.0);

  /* Main computation. We traverse A row-by-row, and for each row:
   *   1) Compute tmp[i] = dot(A[i][:], x[:]).
   *   2) Accumulate y[:] += tmp[i] * A[i][:].
   *
   * Step (1) and (2) each use A[i][:] with j as the innermost index,
   * matching row-major layout and maximizing cache friendliness.
   */
  for (i = 0; i < PB_M; i++)
  {
    const DATA_TYPE *restrict Ai = A_[i];

    /* 1) Compute the dot product into a scalar accumulator.
     *    Only the final value is stored to tmp_[i], avoiding repeated
     *    stores to memory inside the inner loop.
     */
    DATA_TYPE sum = SCALAR_VAL(0.0);
    for (j = 0; j < PB_N; j++)
      sum += Ai[j] * x_[j];

    tmp_[i] = sum;

    /* 2) Use the just-computed tmp_[i] to update y.
     *    Keeping 'sum' in a const local variable encourages the compiler
     *    to keep it in a register throughout the loop.
     */
    const DATA_TYPE t = sum;
    for (j = 0; j < PB_N; j++)
      y_[j] += Ai[j] * t;
  }
#pragma endscop
}


